extern "C" void menuPdaSubCalcAlpha(f32 *alpha,s32 count,s32 selected){f32 step=255.0f*timeGetLastFrameSec();f32 up=step/0.1f;f32 down=step/0.2f;f32*current=alpha;for(s32 i=0;i<count;current++,i++){if(selected==i){if(*current<255.0f){*current+=up;if(*current>255.0f)*current=255.0f;}}else{if(*current>0.0f){*current-=down;if(*current<0.0f)*current=0.0f;}}}}
