extern "C" void menuPdaSubCalcPositon(f32 *position,f32 target,f32 speed){f32 deltaTime=timeGetLastFrameSec();f32 old=*position;f32 diff=target-old;f32 step=30.0f*(speed*deltaTime);if((diff>0.0f?diff:-diff)>=100.0f)step*=30.0f;if(diff<0.0f)step=-step;*position=old+step;diff=target-*position;f32 magnitude=step>0.0f?step:-step;if((diff>0.0f?diff:-diff)<=magnitude)*position=target;}
extern "C" void menuPdaSubScrollBar(tagWINDOW_WORK*w,tagSPRITE_WORK*s,s32 group,s32 id,s32 color,s32 total,s32 visible,s16*first){GSgfxLayer *layer=GSgfxLayerFindByID(winSpriteGetLayerID(w,s));if(!layer)return;if(total>visible)((s8*)s)[4]=(s8)(((u8*)s)[4]|2);else{((s8*)s)[4]=(s8)(((u8*)s)[4]&~2);return;}SubItem*item=menuItemBiosGetPtr(group,id);f32 scale=(f32)item->height/(f32)total;f32 top=scale*(f32)*first;f32 bottom=scale*(f32)(*first+visible);if(layer->blendIndex!=1){layer->blendIndex=1;layer->currentBlend=&layer->blendRecords[layer->blendIndex];}layer->blendMode=1;layer->blendSource=4;layer->blendDestination=5;layer->logicOperation=5;layer->pixelDirty|=1;layer->dirty|=0x40;layer->savedPixelDirty|=1;layer->savedDirty|=0x40;layer->primitiveType=0x80;layer->setRenderStateAndSelect(GSgfxVFGetPredef(3));layer->beginSurface(4);volatile s16*fifo=(volatile s16*)0xCC008000;*fifo=1;*fifo=(s16)top;*fifo=color|w->alpha;*fifo=item->width-2;*fifo=(s16)top;*fifo=color|w->alpha;*fifo=item->width-2;*fifo=(s16)bottom;*fifo=color|w->alpha;*fifo=1;*fifo=(s16)bottom;*fifo=color|w->alpha;layer->endSurface();}
